/** Writes the light metadata modules the eager screens use, so the long article text can load lazily.
 *  Run: node scripts/gen-meta.ts   (a unit test fails if the generated files drift from the content). */
import { writeFileSync } from 'node:fs';
import { guide, guideSections } from '../src/content/guide.ts';
import { chapters } from '../src/content/chapters/full.ts';
import { chapterMetaOf, guideMetaOf } from '../src/content/metaOf.ts';

const head = '// GENERATED by scripts/gen-meta.ts. Do not edit; run `node scripts/gen-meta.ts`.\n';
writeFileSync(
  new URL('../src/content/guideMeta.ts', import.meta.url),
  `${head}import type { GuideSection } from './types.ts';\n\nexport interface GuideMeta { id: string; section: GuideSection; title: string; summary: string; minutes: number }\n\nexport const guideSections: { id: GuideSection; title: string; blurb: string }[] = ${JSON.stringify(guideSections, null, 2)};\n\nexport const guideMeta: GuideMeta[] = ${JSON.stringify(guideMetaOf(guide), null, 2)};\n`,
);
writeFileSync(
  new URL('../src/content/chapters/meta.ts', import.meta.url),
  `${head}export interface ChapterMeta { worldId: string; title: string; minutes: number }\n\nexport const chapterMeta: ChapterMeta[] = ${JSON.stringify(chapterMetaOf(chapters), null, 2)};\n`,
);
